/* kernels/offsets.h — runtime kernel offset table.
 *
 * This file is normally generated by tools/extract_rs/ghostlock-extract from a
 * full OTA.  The exact layout MUST stay in sync with:
 *   - offsets.json  ("symbols" / "struct_fields" entries)
 *   - offsets_json.c (g_symbol_map[] / g_task_map[])
 *
 * W1.5 additions (ghostlock / yuehong-privilege-assistant):
 *   off_modules_disabled, off_oplus_harden_init_succeed, off_oplus_guard_cleanup
 * These three are ABSOLUTE kernel virtual addresses (BSS symbols in the
 * linear/direct-map region), NOT KIMAGE_TEXT_BASE-relative offsets.  They are
 * stored as plain uint64_t and passed directly to do_one_write() WITHOUT
 * going through data_addr().  Keep them together at the end of the struct so
 * the relative-offset fields above remain at stable offsets (offsetof() is
 * used by the JSON parser). */

#ifndef KERNEL_OFFSETS_H
#define KERNEL_OFFSETS_H

#include <stddef.h>
#include <stdint.h>

struct kernel_offsets {
  /* ---- filled from offsets.json "symbols" (text-relative offsets) ---- */
  uintptr_t off_init_task;
  uintptr_t off_init_cred;
  uintptr_t off_root_task_group;
  uintptr_t off_selinux_enforcing;
  uintptr_t off_selinux_blob_sizes;
  uintptr_t off_security_hook_heads;
  uintptr_t off_slide_nfulnl_logger;
  uintptr_t off_slide_loggers_0_1;
  uintptr_t off_slide_boot_id;

  /* 5.15 mcast+plist write primitive (reference kernels). 0 = use the pselect
   * rb_tree route instead.  This field is populated by the extract tool, not
   * by the JSON "symbols" map, so it sits here for layout completeness. */
  int uses_mcast_plist;

  /* ---- filled from offsets.json "struct_fields" (task_struct layout) ---- */
  uint32_t task_prio;
  uint32_t task_normal_prio;
  uint32_t task_sched_task_group;
  uint32_t task_pi_lock;
  uint32_t task_pi_waiters;
  uint32_t task_pi_top_task;
  uint32_t task_pi_blocked_on;
  uint32_t task_pid;
  uint32_t task_tgid;
  uint32_t task_atomic_flags;
  uint32_t task_real_cred;
  uint32_t task_cred;
  uint32_t task_comm;
  uint32_t task_tasks;
  uint32_t task_seccomp;

  /* ---- runtime/derived fields (filled by select_offsets / init_p0_profile) -- */
  const char *uname_r;
  uint64_t kernel_phys_load;
  int pselect_waiter_shift;

  /* ---- W1.5: oplus secure guard bypass (ABSOLUTE kernel virtual addrs) ---- */
  uintptr_t off_modules_disabled;          /* = /proc/kallsyms `modules_disabled` */
  uintptr_t off_oplus_harden_init_succeed; /* oplus_secure_guard_new */
  uintptr_t off_oplus_guard_cleanup;       /* cleanup_module of the guard .ko */
};

#endif /* KERNEL_OFFSETS_H */
